// Screenshots of the Overview at each fixture's telling moment, for docs/screenshots/ and the README
// walkthrough:
//   node player/shoot.ts [--out docs/screenshots] [--only name]
// Each moment is found from the data (a bookmark the player derived from the replay), never from a
// hard-coded time. Drives the locally installed Google Chrome through playwright-core: Playwright's
// own browser builds do not support this macOS 12 machine, so no browser is downloaded.
import { mkdirSync } from 'node:fs';
import { parseArgs } from 'node:util';
import { chromium } from 'playwright-core';
import { SystemClock } from '../src/clock.ts';
import type { Player } from './player.ts';
import { startPlayerServer } from './server.ts';

export interface Shot {
  file: string;
  fixture: string;
  // The moment: a bookmark's text (first match), plus an offset after it.
  mark: RegExp | null;
  after: number;
  shows: string;
}

export const SHOTS: Shot[] = [
  { file: '01-frozen-truck.png', fixture: 'frozen-truck', mark: /HT-10 data frozen/, after: 20_000, shows: 'HT-10 reports tramming at 2 m/s but its position has not moved: drawn as a cross-hatched bar over everywhere it could have reached since it last moved, wrapping from TIP round into BAY, with a hollow circle at its last believable position. "contradicted" in the table. The other eleven trucks have not reported yet in this recording, so they share one dotted whole-loop bar.' },
  { file: '02-frozen-truck-loading-contrast.png', fixture: 'frozen-truck', mark: null, after: Number.POSITIVE_INFINITY, shows: 'End of the same recording: HT-05 loading sends identical messages too, but at speed 0 in a stationary state, so it is a solid live chip. HT-10, quiet by now, is a silent hatched bar.' },
  { file: '03-silent-truck-old.png', fixture: 'silent-truck', mark: /HT-03 silent/, after: -2_500, shows: 'HT-03 two and a half seconds after its last message: an old chip, grey with a dashed edge and its age, while the site link (heartbeats) is up.' },
  { file: '04-silent-truck.png', fixture: 'silent-truck', mark: /HT-03 silent/, after: 25_000, shows: 'HT-03 silent for about 30 s: a hatched bar over everywhere it could have reached, its last position marked, "silent 30 s" in the table, the site link still up.' },
  { file: '05-link-drop-in-notice.png', fixture: 'link-drop-in-notice', mark: /site link down/, after: 15_000, shows: 'DRAW_12 closing and the site link down 20 s: the picture greys, a banner gives the age, DRAW_12 is UNSURE with "Radio the shot firer to hold the shot", and its countdown keeps running.' },
  { file: '06-two-zones-closing.png', fixture: 'two-zones-closing', mark: null, after: 5_000, shows: 'DRAW_12 and TIP both closing, each with its own countdown and its own clearance row. No truck has reported yet, so both are UNSURE: never CLEAR.' },
  { file: '07-two-zones-one-closed.png', fixture: 'two-zones-closing', mark: /TIP CLOSED/, after: 3_000, shows: 'TIP closed (hatched band, "closed 0:03 ago") while DRAW_12 is still closing.' },
  { file: '08-weak-pack-draining.png', fixture: 'weak-pack', mark: /HT-06 battery: draining/, after: 0, shows: 'HT-06 flagged draining faster than the fleet, with the ratio, under the pack\'s own figure.' },
  { file: '09-weak-pack-warning.png', fixture: 'weak-pack', mark: /HT-06 battery: (May not reach|Will not finish)/, after: 0, shows: 'HT-06 warned while it can still act: the warning names the action (return to bay) and the truck rises to the top of the table.' },
  { file: '10-weak-pack-depleted.png', fixture: 'weak-pack', mark: /HT-06 battery: Battery depleted/, after: 5_000, shows: 'HT-06 BATTERY_DEPLETED in the incline: fault mark on its chip, "faulted (BATTERY_DEPLETED)" and "depleted: needs a tow" in the table, first row.' },
  { file: '11-fractional-soc.png', fixture: 'fractional-soc', mark: null, after: 8_000, shows: 'HT-12 sends its charge as a fraction: shown as sent ("0.82 (as sent)") with a flag, never scaled to 82 %.' },
  { file: '12-reverse-exit-zone.png', fixture: 'reverse-exit-zone', mark: /probe sent EXIT_ZONE/, after: 20_000, shows: 'HT-05 reversing up DECLINE under EXIT_ZONE: "◀ reversing" on its chip, EXIT_ZONE in the state column. The last-command column is a placeholder until the command registry exists.' },
  { file: '13-seq-reset.png', fixture: 'seq-reset', mark: /controller restarted/, after: 3_000, shows: 'HT-01 after its controller restarted (seq 887 to 1): still live, still moving on the line.' },
];

async function moment(player: Player, s: Shot): Promise<number> {
  player.load(s.fixture);
  const f = player.frame().player;
  let base = 0;
  if (s.mark) {
    const b = f.bookmarks.find((x) => s.mark!.test(x.text));
    if (!b) throw new Error(`${s.file}: no bookmark matching ${s.mark} in ${s.fixture}: ${f.bookmarks.map((x) => x.text).join(' | ')}`);
    base = b.offsetMs;
  }
  return Math.max(0, Math.min(base + s.after, f.endMs - f.startMs));
}

if (import.meta.main) {
  const { values } = parseArgs({ options: { out: { type: 'string', default: 'docs/screenshots' }, only: { type: 'string' } } });
  mkdirSync(values.out, { recursive: true });
  const server = await startPlayerServer({ clock: new SystemClock(), fixture: 'frozen-truck' });
  const browser = await chromium.launch({ channel: 'chrome', headless: true });
  try {
    const page = await browser.newPage({ viewport: { width: 1440, height: 1200 }, colorScheme: 'dark' });
    for (const s of SHOTS.filter((x) => !values.only || x.file.includes(values.only))) {
      const t = await moment(server.player, s);
      await page.goto(`${server.url}?fixture=${s.fixture}&t=${t}`);
      await page.waitForSelector('#rows tr');
      await page.waitForTimeout(600); // let chips settle after their 200 ms glide
      await page.screenshot({ path: `${values.out}/${s.file}`, fullPage: true });
      console.log(`${s.file}  ${s.fixture} +${(t / 1000).toFixed(1)} s`);
    }
  } finally {
    await browser.close();
    await server.close();
  }
}

